function isAssessmentVisit(j){return j.opsAction==='assessment'||j.routeOverride==='assessment'}
/* Client-selected call-outs have a budget on submission; one booking writes both calendars. */
const normaliseBeforeBookingWorkflow=normalise;
normalise=function(){normaliseBeforeBookingWorkflow();for(const j of state.jobs){if(!j.callout)continue;const c=j.callout;if(c.status!=='Approved'||!Number.isFinite(c.totalBudget)||c.totalBudget<=0){j.clientServicePreference='callout';j.callout=null;j.status='Awaiting property manager review';j.dispatchStatus='Awaiting property manager review';j.sentToSevlink=false;j.assigned=false;j.opsAction=null;j.reviewedAt=null;j.schedule=null}else if(c.overrun?.status==='Pending'){j.quoteNeeded={status:'Required',estimatedTotal:c.overrun.total,notes:c.overrun.notes,at:c.overrun.requestedAt||now()};c.overrun=null;c.outcome='quote';j.previousVisit=j.schedule;j.schedule=null;j.opsAction='quoting';j.status='New'}}};
requestCallout=async function(){toast('Call-outs are selected and budgeted by the agency when submitting the job.');return false};
routeCallout=async function(){return requestCallout()};
calloutForm=function(){toast('The agency selects the call-out and supplies its budget with the job.')};
decideCalloutOverrun=async function(){toast('Further work requires a quote. There is no call-out budget approval request.');return false};
overrunApprovalForm=function(){};
calloutBudgetPanel=function(j){if(!j.callout)return '';return `<div class="notice"><b>Call-out · client budget supplied</b>${role!=='tenant'?`<p>Maximum total budget: <b>${money(j.callout.totalBudget)}</b>${j.callout.actualTotal!=null?'<br>Recorded total: '+money(j.callout.actualTotal):''}</p>`:''}${j.quoteNeeded?'<p>Further work requires a quote. Sevlink will discuss the findings with the client.</p>':'<p>Complete within the client budget, then invoice.</p>'}</div>`};
const approvedBeforeBookingWorkflow=approved;
approved=function(j){if(j.quoteNeeded)return j.quotes.some(q=>q.status==='Approved'&&q.approvedForFollowup);return approvedBeforeBookingWorkflow(j)};
finishSimpleCallout=async function(jid,total,notes,checks='',photo=null){const j=getJob(jid);if(!j||role!=='sevlink'||j.callout?.status!=='Approved'||j.quoteNeeded||!['Scheduled','In progress'].includes(j.status)||!Number.isFinite(total)||total<0||!notes?.trim())return false;const over=total>j.callout.totalBudget;const ok=await commit(()=>{if(over){j.quoteNeeded={status:'Required',estimatedTotal:total,notes,at:now()};j.callout.overrun=null;j.callout.outcome='quote';j.previousVisit=j.schedule;j.schedule=null;j.opsAction='quoting';j.status='New';addEvent(j,'Further work requires a quote','Findings recorded. Sevlink will discuss the required quote with the client.');addEvent(j,'Estimated total for follow-up quote',money(total),'financial');if(photo){photo.phase='before';photo.at=now();j.photos.push(photo);j.beforePhotos.push(photo)}}else{j.callout.actualTotal=total;j.callout.findings=notes;j.status='Completed';j.completedAt=now();j.completionNotes=notes;j.completionChecks=checks||'Completion recorded by Sevlink.';if(photo){photo.phase='after';photo.at=now();j.photos.push(photo);j.afterPhotos.push(photo)}addEvent(j,'Call-out completed','Completed within client budget; ready to invoice.');addEvent(j,'Call-out total',money(total),'financial')}});return ok?(over?'quote':'invoice'):false};
simpleCalloutCompletion=function(jid){const j=getJob(jid);if(!j||role!=='sevlink'||!j.callout||!['Scheduled','In progress'].includes(j.status))return;if(j.quoteNeeded){completionBeforeSimpleCallout(jid);return}openForm('Complete call-out or record quote needed.',`<div class="notice">Client maximum total budget: <b>${money(j.callout.totalBudget)}</b></div><label>Total / estimated total (ZAR)</label><input name="total" type="number" required min="0" max="10000000" step="0.01" value="${j.callout.actualTotal??''}"><label>Work completed / findings</label><textarea name="notes" rows="4" required maxlength="2500"></textarea><label>Checks / recommendations (optional)</label><textarea name="checks" rows="2" maxlength="1500"></textarea><label>Photo (optional)</label><input name="photo" type="file" accept="image/jpeg,image/png,image/webp"><div class="notice">Within budget: complete and invoice.<br>Above budget: record that a quote is required, then contact the client. No budget approval request is sent.</div>`,'Save & continue',async d=>{let photo;try{photo=await fileData(d.get('photo'),imageTypes)}catch(e){toast(e.message);return}const result=await finishSimpleCallout(jid,Number(d.get('total')),d.get('notes'),d.get('checks'),photo);if(!result)return;render();if(result==='quote'){jobDetail(jid,'quotes');toast('Moved to Quoting. Contact the client, then provide a quote.')}else{invoiceForm(jid);toast('Completed. Upload the invoice.')}})};
const quotesBeforeBookingWorkflow=renderQuotes;renderQuotes=function(j){if(j.callout&&j.quoteNeeded)return quotesBeforeSimpleCallout(j);return quotesBeforeBookingWorkflow(j)};
const detailBeforeBookingWorkflow=jobDetail;jobDetail=function(jid,section='comments'){detailBeforeBookingWorkflow(jid,section);const j=getJob(jid);if(j?.callout&&j.quoteNeeded){const tabs=$('.tabs');tabs.insertAdjacentHTML('beforeend',`<button onclick="jobDetail('${jid}','quotes')">Follow-up quote</button>`);if(section==='quotes')renderQuotes(j)}};
const approveBeforeBookingWorkflow=approve;approve=async function(jid,qid){const j=getJob(jid),q=j?.quotes.find(q=>q.id===qid);if(j?.quoteNeeded&&role==='manager'&&q?.status==='Pending'){if(await commit(()=>{j.quotes.forEach(x=>{if(x.status==='Approved'||x.status==='Pending')x.status=x.id===qid?'Approved':'Not selected'});q.status='Approved';q.approvedForFollowup=true;j.quoteNeeded.status='Approved';j.quoteNeeded.approvedQuote=qid;j.status='Awaiting schedule';j.schedule=null;j.assigned=true;addEvent(j,'Follow-up quote approved',q.supplier+' · '+money(q.amount),'financial');notify(j,'Quote approved',j.ref+': follow-up work approved.')})){render();jobDetail(jid,'quotes');toast('Follow-up quote approved. Arrange the return visit.')}return}return approveBeforeBookingWorkflow(jid,qid)};
const nextBeforeBookingWorkflow=nextAction;nextAction=function(j){if(j.quoteNeeded&&j.quoteNeeded.status==='Required'&&jobStage(j)==='quoting')return 'Contact client and prepare a follow-up quote';if(j.callout&&jobStage(j)==='underway')return j.quoteNeeded?'Complete approved quoted work':'Complete within budget and invoice';return nextBeforeBookingWorkflow(j)};
bookingForm=function(bid='',jobid=''){if(role!=='sevlink')return;const b=state.privateBookings.find(x=>x.id===bid),jobs=visibleJobs().filter(j=>!['Completed','Cancelled'].includes(j.status)),fixedId=b?.job||jobid,fixed=jobs.find(j=>j.id===fixedId);if(!state.subbies.length){toast('Add a subbie first.');return}if(!jobs.length||fixedId&&!fixed){toast('This job is not available for booking.');return}openForm(b?'Edit booked visit.':'Assign subbie & book visit.',`${fixed?`<input type="hidden" name="job" value="${fixed.id}"><div class="notice"><b>${esc(property(fixed.property)?.name)}</b><br>${esc(property(fixed.property)?.address)}<br>${fixed.ref} · ${esc(fixed.title)}</div>`:`<label>Choose the job</label><select name="job">${jobs.map(j=>`<option value="${j.id}">${esc(property(j.property)?.name)} · ${j.ref} · ${esc(j.title)}</option>`).join('')}</select>`}<label>Subbie</label><select name="subbie">${state.subbies.map(s=>`<option value="${s.id}" ${b?.subbie===s.id?'selected':''}>${esc(s.name)} — ${esc(s.trade)}</option>`).join('')}</select><label>Agreed attendance date & time (SAST)</label><input name="when" type="datetime-local" required value="${esc(b?.when||fixed?.schedule?.when||'')}"><div class="row"><div><label>Duration (hours)</label><input name="hours" type="number" min="0.25" max="12" step="0.25" value="${(b?.duration||60)/60}" required><small>e.g. 1, 1.5 or 2 hours</small></div><div><label>Subbie price (private)</label><input name="price" type="number" min="0" max="10000000" step="0.01" value="${b?.price??''}" required></div></div><label>Private instructions for the subbie</label><textarea name="instructions" rows="3" maxlength="2000" required>${esc(b?.instructions||'')}</textarea><label>Private Sevlink notes</label><textarea name="internalNote" rows="2" maxlength="2000">${esc(b?.internalNote||'')}</textarea><label>Shared appointment / access notes (client can see)</label><textarea name="clientNote" rows="3" maxlength="1500">${esc(fixed?.schedule?.note||'')}</textarea><label style="display:flex;align-items:center;gap:10px"><input name="agreed" type="checkbox" style="width:auto" required>I have confirmed this date and time with the subbie and the client.</label><div class="notice">Saving books both calendars immediately. The client sees Sevlink attending, the time and shared notes. Subbie details, cost and private instructions stay in the private planner.</div>`,'Save booking to both calendars',async d=>{const record={job:fixed?.id||d.get('job'),subbie:d.get('subbie'),when:d.get('when'),duration:Number(d.get('hours'))*60,price:Number(d.get('price')),instructions:d.get('instructions'),internalNote:d.get('internalNote'),clientNote:d.get('clientNote'),confirmBooking:true,agreed:!!d.get('agreed')};if(await savePrivateBooking(bid,record)){modal.close();navigate('privateplanner');toast('Visit booked in the private planner and maintenance calendar.')}})};
const privateSaveBeforeBookingWorkflow=savePrivateBooking;
savePrivateBooking=async function(bid,record){if(!record.confirmBooking)return privateSaveBeforeBookingWorkflow(bid,record);const j=getJob(record.job),existing=state.privateBookings.find(b=>b.id===bid);if(role!=='sevlink'||!j||j.sentToSevlink===false||j.status==='Completed'||existing&&existing.job!==record.job||!state.subbies.some(s=>s.id===record.subbie))return false;if(!record.agreed){toast('Confirm the agreed date and time before booking.');return false}if(j.callout&&(!Number.isFinite(j.callout.totalBudget)||j.callout.totalBudget<=0)){toast('The agency must provide the call-out budget with the job.');return false}if(j.status==='Awaiting approval'&&j.quotes.some(q=>q.status==='Pending')){toast('The pending quote must be resolved before booking work.');return false}if(!approved(j)&&!isAssessmentVisit(j)){toast('The client must accept the quote before this job can be booked.');return false}const start=Date.parse(record.when+'+02:00');if(!Number.isFinite(start)||start<=Date.now()||!Number.isFinite(record.duration)||record.duration<15||record.duration>720||!Number.isFinite(record.price)||record.price<0){toast('Enter a future date, valid duration and private price.');return false}const overlapAuth=record.overlapAuthorisation;const canOverlap=role==='sevlink'&&overlapAuth?.reason?.trim()&&state.sevlinkStaff?.some(s=>s.id===overlapAuth.staffId);if(overlappingBooking(record.subbie,record.when,record.duration,bid)&&!canOverlap){toast('This subbie already has an overlapping booking. Authorise the conflict with a reason first.');return false}if(state.privateBookings.some(b=>b.id!==bid&&b.job===record.job&&!['Cancelled','Declined','Attended'].includes(b.status))){toast('Edit the active booking on this job instead.');return false}const end=start+record.duration*60000,conflict=state.jobs.find(other=>{if(other.id===j.id||other.status==='Completed'||other.schedule?.status!=='Confirmed')return false;const otherBooking=activeJobBooking(other.id);if(otherBooking&&otherBooking.subbie!==record.subbie)return false;if(!otherBooking&&other.team!==j.team)return false;return start<Date.parse(other.schedule.when+'+02:00')+(otherBooking?.duration||other.duration||60)*60000&&end>Date.parse(other.schedule.when+'+02:00')});if(conflict&&!canOverlap){toast('An overlapping attendance booking needs to be resolved first.');return false}return commit(()=>{const values={job:record.job,subbie:record.subbie,when:record.when,duration:record.duration,price:record.price,instructions:record.instructions,internalNote:record.internalNote,status:'Accepted',acceptedAt:now()};let booking=existing;if(booking){Object.assign(booking,values);booking.log.push({at:now(),text:'Agreed booking updated and linked to client maintenance calendar.'})}else{booking={id:id('booking'),...values,createdAt:now(),log:[{at:now(),text:'Subbie and client date confirmed; both calendars booked.'}]};state.privateBookings.push(booking)}const changed=j.schedule?.when!==record.when||j.schedule?.status!=='Confirmed';j.schedule={when:record.when,note:record.clientNote||'',by:'Sevlink',status:'Confirmed',at:now()};j.attendancePurpose=isAssessmentVisit(j)?'Assessment':'Repair';j.duration=record.duration;j.status='Scheduled';j.assigned=true;if(changed)j.access={status:'Awaiting tenant',note:''};addEvent(j,'Sevlink attendance booked',attendanceTime(record.when)+(record.clientNote?' · '+record.clientNote:''));j.history.push('Sevlink appointment booked for '+attendanceTime(record.when));booking.publicBookingAt=now();if(canOverlap){booking.overlapAuthorisations??=[];const staff=state.sevlinkStaff.find(s=>s.id===overlapAuth.staffId);const auth={by:staff.name,staffId:staff.id,reason:overlapAuth.reason.trim(),at:now(),when:record.when,duration:record.duration};booking.overlapAuthorisations.push(auth);booking.log.push({at:auth.at,text:'Overlapping teams authorised by '+auth.by+': '+auth.reason})}})};
function endAttendance(j){if(!j.schedule)return '';const end=new Date(Date.parse(j.schedule.when+'+02:00')+(j.duration||60)*60000);return new Intl.DateTimeFormat('en-ZA',{hour:'2-digit',minute:'2-digit',hourCycle:'h23',timeZone:'Africa/Johannesburg'}).format(end)}
renderCalendar=function(){const jobs=calendarJobs(),year=calendarMonth.getFullYear(),month=calendarMonth.getMonth(),days=new Date(year,month+1,0).getDate(),offset=(new Date(year,month,1).getDay()+6)%7;app.innerHTML=heading('Sevlink maintenance calendar.','Booked and attended appointments for your properties. Open a visit for the full repair record.')+`<div class="panel"><div class="panelhead"><button class="secondary" onclick="moveMonth(-1)">← Previous</button><h2>${calendarMonth.toLocaleDateString('en-ZA',{month:'long',year:'numeric'})}</h2><button class="secondary" onclick="moveMonth(1)">Next →</button></div><div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="cal-head">${d}</div>`).join('')}${Array.from({length:offset},()=>'<div class="cal-day muted"></div>').join('')}${Array.from({length:days},(_,i)=>{const key=year+'-'+String(month+1).padStart(2,'0')+'-'+String(i+1).padStart(2,'0');return `<div class="cal-day"><b>${i+1}</b>${jobs.filter(j=>j.schedule.when.startsWith(key)).map(j=>`<button class="cal-event" onclick="openCalendarAppointment('${j.id}','${j.schedule.when}')"><b>${j.schedule.when.slice(11)}–${endAttendance(j)}</b> · ${j.schedule.status==='Attended'?'✓ Attended':j.schedule.onSiteAt?'● Sevlink on site':'Sevlink attending'}<strong class="calendar-issue">${esc(j.title||j.category||'Maintenance visit')}</strong><small>${esc(property(j.property)?.name)}</small></button>`).join('')}</div>`}).join('')}</div></div><div class="panel" style="margin-top:20px"><h2>Booked & attended appointment details</h2>${jobs.sort((a,b)=>a.schedule.when.localeCompare(b.schedule.when)).map(j=>`<div class="listline"><div class="toolbar"><div style="flex:1"><span class="eyebrow">${j.schedule.status==='Attended'?'SEVLINK ATTENDED':'SEVLINK ATTENDING'} · ${j.ref}</span><h2 style="margin-top:8px">${esc(property(j.property)?.name)}</h2><p>${esc(property(j.property)?.address)}<br><b>${attendanceTime(j.schedule.when)} – ${endAttendance(j)}</b><br>${esc(j.title)} · ${esc(j.status)}</p><p>${esc(j.description)}</p><p><b>Shared appointment notes:</b> ${esc(j.schedule.note||'No additional notes.')}<br><b>Property access instructions:</b> ${esc(j.clientInstructions||j.access?.note||'To be confirmed')}<br><b>Tenant access:</b> ${esc(j.access?.status||'Awaiting tenant')}</p></div><div class="actions"><button class="secondary" onclick="openCalendarAppointment('${j.id}','${j.schedule.when}')">Open visit</button></div></div></div>`).join('')||'<p>No confirmed appointments yet. A saved agreed booking appears here automatically.</p>'}</div>`};

const invoiceBeforeBookingWorkflow=invoiceForm;
invoiceForm=function(jid){const j=getJob(jid),q=j?.quotes.find(q=>q.status==='Approved'&&q.approvedForFollowup);if(!j?.quoteNeeded||!q)return invoiceBeforeBookingWorkflow(jid);if(role!=='sevlink'||j.status!=='Completed'){toast('Complete the approved quoted work before invoicing.');return}invoiceBeforeSimpleCallout(jid);const input=modal.querySelector('input[name="amount"]');if(input)input.value=q.amount;const form=$('#form'),submit=form.onsubmit;form.onsubmit=async e=>{const amount=Number(new FormData(form).get('amount')),existing=(j.invoices||[]).reduce((n,i)=>n+i.amount,0);if(!Number.isFinite(amount)||amount>q.amount||existing+amount>j.callout.totalBudget+q.amount){e.preventDefault();toast('The invoice must stay within the approved quoted amount.');return}return submit(e)}};
